import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:allcheck_ui/allcheck_ui.dart';

AppStore driver(){final s=AppStore(AppRole.driver);s.data['account']=<String,dynamic>{'status':'활성','profile':<String,dynamic>{'name':'기사'}};return s;}
void main(){
  test('driver assignment order, cancellation and account gate',(){final s=driver(),id=s.addSampleRequest();s.respond(id,true);expect(()=>s.advance(id,'작업 완료'),throwsStateError);s.advance(id,'현장 도착');s.advance(id,'작업 중');s.cancelWork(id,'일정 충돌');expect(s.job(id)['assigned'],false);expect(()=>s.advance(id,'작업 완료'),throwsStateError);s.account!['status']='승인 대기';expect(()=>s.addSampleRequest(),throwsStateError);});
  test('report needs complete assignment, photos and is idempotently restricted',(){final s=driver(),id=s.addSampleRequest();s.respond(id,true);s.advance(id,'현장 도착');s.advance(id,'작업 중');s.advance(id,'작업 완료');expect(()=>s.submitReport(id,<String,dynamic>{}),throwsStateError);final report=<String,dynamic>{'before':<Json>[<String,dynamic>{'base64':'AA=='}],'after':<Json>[<String,dynamic>{'base64':'AA=='}],'content':'내용','diagnosis':'진단','cost':'10000'};s.submitReport(id,report);expect(()=>s.submitReport(id,report),throwsStateError);expect(s.reports.length,1);});
  test('withdrawal blocked while assigned; message retry does not duplicate',(){final s=driver(),id=s.addSampleRequest();s.respond(id,true);expect(s.withdraw,throwsStateError);final m=s.sendMessage('','문의',fail:true,requestId:'one');s.sendMessage('','문의',fail:true,requestId:'one');s.retryMessage('',text(m,'id'));expect(s.messages.length,1);expect(()=>s.retryMessage('',text(m,'id')),throwsStateError);});
  test('failed storage write rolls state back',()async{final s=AppStore(AppRole.admin,save:(_)async=>throw StateError('disk full'));final before=jsonEncode(s.data);await expectLater(s.change(()=>s.seedAdmin()),throwsStateError);expect(jsonEncode(s.data),before);expect(s.saving,false);});
  test('manual AI failure review gates and deduplicates registration',(){final s=AppStore(AppRole.admin);s.seedAdmin();expect(()=>s.registerReception('example-failed'),throwsStateError);s.reviewReception('example-failed',<String,dynamic>{'customer':'고객','phone':'01000000000','address':'서울 강남구','type':'막힘','symptom':'배수 불량'});final id=s.registerReception('example-failed');expect(s.job(id)['status'],'배차 대기');expect(()=>s.registerReception('example-failed'),throwsStateError);});
  test('delivery distinguishes all failure from partial result',(){final s=AppStore(AppRole.admin);s.seedAdmin();s.dispatch('example-cancel-job',['example-active'],'partial');expect((s.job('example-cancel-job')['dispatch']as Json)['status'],'전체 전달 실패');s.dispatch('example-cancel-job',['example-active','example-other'],'partial');expect((s.job('example-cancel-job')['dispatch']as Json)['status'],'일부 전달 실패');});
  test('approval validates business and rejects repeated decisions',(){final s=AppStore(AppRole.admin);s.seedAdmin();expect(()=>s.decideDriver('example-incomplete',true,''),throwsStateError);expect(()=>s.decideDriver('example-pending',false,''),throwsStateError);s.decideDriver('example-pending',false,'보완');expect(()=>s.decideDriver('example-pending',true,''),throwsStateError);});
  test('report original and immutable photos preserved with itemized totals',(){final s=AppStore(AppRole.admin);s.seedAdmin();final r=s.reports['example-completed']as Json,original=jsonEncode(r['original']);s.editReport('example-completed',<String,dynamic>{'content':'수정','diagnosis':'진단','travelCost':'30000','materialCost':'25000','laborCost':'50000'},'관리자');expect((r['current']as Json)['cost'],'105000');expect(jsonEncode(r['original']),original);expect(records(r['history']).length,1);s.data['role']='viewer';expect(()=>s.editReport('example-completed',<String,dynamic>{},'관리자'),throwsStateError);});
  test('cancellation resolves once and read-only chat is enforced',(){final s=AppStore(AppRole.admin);s.seedAdmin();s.resolveCancellation('example-cancellation',true);expect(()=>s.resolveCancellation('example-cancellation',false),throwsStateError);expect(()=>s.sendMessage('example-withdrawn','문의'),throwsStateError);});
  test('schema round-trip preserves both roles independently',(){final s=driver();s.addSampleRequest();final restored=AppStore(AppRole.driver);restored.restore(jsonEncode(s.data));expect(restored.jobs.length,1);expect(AppStore(AppRole.admin).jobs,isEmpty);expect(()=>restored.restore('{}'),throwsFormatException);});
  test('xlsx has ZIP header and string cells rather than formulas',(){final data=xlsxBytes([['=1+1','<고객>']]);expect(ByteData.sublistView(data).getUint32(0,Endian.little),0x04034b50);final decoded=utf8.decode(data,allowMalformed:true);expect(decoded,contains('inlineStr'));expect(decoded,contains('&lt;고객&gt;'));expect(decoded,isNot(contains('<f>')));});
  testWidgets('both roles have independent Flutter login widgets', (tester)async{await tester.pumpWidget(AllcheckApp(role:AppRole.driver,store:AppStore(AppRole.driver)));await tester.pump();expect(find.text('ALLCHECK'),findsOneWidget);expect(find.text('Apple로 시작하기'),findsOneWidget);await tester.pumpWidget(const SizedBox());await tester.pumpWidget(AllcheckApp(role:AppRole.admin,store:AppStore(AppRole.admin)));await tester.pump();expect(find.byType(TextFormField),findsNWidgets(2));await tester.pumpWidget(const SizedBox());});
}
